const NET_PRESETS={cross:[[1,0],[0,1],[1,1],[2,1],[3,1],[1,2]],overlap:[[0,0],[1,0],[2,0],[0,1],[1,1],[2,1]]};
const labMul=(v,k)=>v.map(x=>x*k);
